### Description
This Terraform configuration sets up two Elastic Beanstalk environments in different AWS regions (`us-west-2` and `eu-central-1`). It also configures a Route53 hosted zone and records to route traffic to the closest environment based on the user's geolocation. The `us_west` environment is associated with the United States, and the `eu_central` environment is associated with Europe.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_elastic_beanstalk_application" "example_app" {
  name        = "example-app"
  description = "Example Elastic Beanstalk Application"
}

resource "aws_elastic_beanstalk_environment" "us_west_environment" {
  name                = "us_west"
  application         = aws_elastic_beanstalk_application.example_app.name
  solution_stack_name = "64bit Amazon Linux 2 v3.5.0 running Python 3.8"
}

resource "aws_elastic_beanstalk_environment" "eu_central_environment" {
  provider = aws.eu_central

  name                = "eu_central"
  application         = aws_elastic_beanstalk_application.example_app.name
  solution_stack_name = "64bit Amazon Linux 2 v3.5.0 running Python 3.8"
}

provider "aws" {
  alias  = "eu_central"
  region = "eu-central-1"
}

resource "aws_route53_zone" "example_com_zone" {
  name = "example.com"
}

resource "aws_route53_record" "us_west_record" {
  name       = "www.example.com"
  type       = "A"
  zone_id    = aws_route53_zone.example_com_zone.zone_id
  ttl        = 300

  geolocation_routing_policy {
    country = "US"
  }

  alias {
    name                   = aws_elastic_beanstalk_environment.us_west_environment.endpoint_url
    zone_id                = aws_elastic_beanstalk_environment.us_west_environment.cname
    evaluate_target_health = true
  }
}

resource "aws_route53_record" "eu_central_record" {
  name       = "www.example.com"
  type       = "A"
  zone_id    = aws_route53_zone.example_com_zone.zone_id
  ttl        = 300

  geolocation_routing_policy {
    country = "EU"
  }

  alias {
    name                   = aws_elastic_beanstalk_environment.eu_central_environment.endpoint_url
    zone_id                = aws_elastic_beanstalk_environment.eu_central_environment.cname
    evaluate_target_health = true
  }
}
```

### Explanation
1. **Provider Configuration**: Two provider configurations are defined, one for `us-west-2` and another aliased as `eu_central` for `eu-central-1`.
2. **Elastic Beanstalk Application**: A single Elastic Beanstalk application is created.
3. **Elastic Beanstalk Environments**: Two environments are created, one in each region. The `eu_central_environment` uses the `eu_central` provider alias.
4. **Route53 Zone and Records**: A Route53 hosted zone is created, and two records are set up to route traffic to the respective environments based on geolocation.

