Here is the updated Terraform configuration:

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "kinesis_analytics_role" {
  name = "kinesis-analytics-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
