  # Correcting the block name from 'notification' to 'notification_configuration'
  notification_configuration {
    topic_configuration {
      topic_arn = aws_sns_topic.s3_event_notification_topic.arn
      event     = "s3:ObjectCreated:*"
      filter {
        key {
          prefix = ""
          suffix = ".log"
        }
      }
    }
  }

  depends_on = [
    aws_sns_topic.s3_event_notification_topic,
    aws_iam_policy.s3_publish_to_sns_policy
  ]
}
