### Description
This Terraform program creates a VPC in the `us-east-1` region, along with two subnets in the availability zones `east-1a` and `east-1b`. It also creates a Redshift subnet group that includes these two subnets.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_vpc" "my_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "subnet_east_1a" {
  vpc_id            = aws_vpc.my_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-east-1a"
}

resource "aws_subnet" "subnet_east_1b" {
  vpc_id            = aws_vpc.my_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-east-1b"
}

resource "aws_redshift_subnet_group" "redshift_subnet_group" {
  name       = "redshift-subnet-group"
  subnet_ids = [aws_subnet.subnet_east_1a.id, aws_subnet.subnet_east_1b.id]
}
```

This configuration ensures that the VPC, subnets, and Redshift subnet group are created in the specified region and availability zones, adhering to the requirements provided in the prompt.

