    stream_mode = "ON_DEMAND"
  }
}

resource "aws_dynamodb_kinesis_streaming_destination" "my_dynamodb_kinesis_streaming_destination" {
  stream_arn = aws_kinesis_stream.my_kinesis_stream.arn
  table_name = aws_dynamodb_table.my_dynamodb_table.name
}
