LLM Output #0:
### Description
This Terraform program creates a managed Amazon Managed Streaming for Apache Kafka (MSK) cluster with 3 broker nodes in the `us-east-1` region. The program includes the necessary configuration for the MSK cluster, including the `broker_node_group_info` nested block which specifies the client subnets, instance type, and security groups. Additionally, it ensures that the VPC and subnets are properly configured and exist before creating the MSK cluster.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_vpc" "example_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "example_subnet_1" {
  vpc_id            = aws_vpc.example_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-east-1a"
}

resource "aws_subnet" "example_subnet_2" {
  vpc_id            = aws_vpc.example_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-east-1b"
}

resource "aws_subnet" "example_subnet_3" {
  vpc_id            = aws_vpc.example_vpc.id
  cidr_block        = "10.0.3.0/24"
  availability_zone = "us-east-1c"
}

resource "aws_security_group" "example_sg" {
  vpc_id = aws_vpc.example_vpc.id

  ingress {
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_role" "msk_role" {
  name = "msk-cluster-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "msk_policy" {
  role       = aws_iam_role.msk_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonMSKFullAccess"
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name           = "example-msk-cluster"
  kafka_version          = "2.8.0"
  number_of_broker_nodes = 3

  broker_node_group_info {
    client_subnets = [aws_subnet.example_subnet_1.id, aws_subnet.example_subnet_2.id, aws_subnet.example_subnet_3.id]
    instance_type  = "t3.medium"
    security_groups = [aws_security_group.example_sg.id]
  }

  depends_on = [aws_iam_role_policy_attachment.msk_policy]
}
```

This Terraform configuration sets up a VPC with three subnets across different availability zones, a security group to allow traffic on port 9092, and an IAM role with the necessary permissions for the MSK cluster. The MSK cluster itself is configured with three broker nodes using the specified instance type and security group.

