LLM Output #0:
### Description

This Terraform program creates a managed Amazon MSK (Managed Streaming for Apache Kafka) cluster in the `us-east-1` region and configures it to log to an Amazon Kinesis Firehose delivery stream. The program includes the necessary IAM roles and policies to allow the MSK cluster to send logs to the Kinesis Firehose.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

# IAM Role for MSK to send logs to Kinesis Firehose
resource "aws_iam_role" "msk_firehose_role" {
  name = "msk-firehose-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for MSK to send logs to Kinesis Firehose
resource "aws_iam_policy" "msk_firehose_policy" {
  name        = "msk-firehose-policy"
  description = "Policy for MSK to send logs to Kinesis Firehose"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "firehose:PutRecord",
          "firehose:PutRecordBatch"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach the policy to the role
resource "aws_iam_role_policy_attachment" "msk_firehose_policy_attachment" {
  policy_arn = aws_iam_policy.msk_firehose_policy.arn
  role       = aws_iam_role.msk_firehose_role.name
}

# Kinesis Firehose Delivery Stream
resource "aws_kinesis_firehose_delivery_stream" "msk_logs_firehose" {
  name        = "msk-logs-firehose"
  destination = "extended_s3"

  extended_s3_configuration {
    role_arn   = aws_iam_role.msk_firehose_role.arn
    bucket_arn = "arn:aws:s3:::your-s3-bucket-name"
  }
}

# MSK Cluster
resource "aws_msk_cluster" "managed_msk_cluster" {
  cluster_name           = "managed-msk-cluster"
  kafka_version          = "2.8.1"
  number_of_broker_nodes = 3

  broker_node_group_info {
    client_subnets = ["subnet-0123456789abcdef0", "subnet-0123456789abcdef1", "subnet-0123456789abcdef2"]
    instance_type  = "t3.medium"
    security_groups = ["sg-0123456789abcdef0"]
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = "/aws/msk/cluster"
      }
      firehose {
        enabled         = true
        delivery_stream = aws_kinesis_firehose_delivery_stream.msk_logs_firehose.name
      }
    }
  }
}
```

### Notes
- Replace `"arn:aws:s3:::your-s3-bucket-name"` with the ARN of your S3 bucket where you want to store the logs.
- Ensure that the subnets and security groups provided in the `broker_node_group_info` block are correctly configured in your AWS account.
- The IAM role and policy ensure that the MSK cluster has the necessary permissions to send logs to the Kinesis Firehose delivery stream.

