### Description
This Terraform program creates a serverless Amazon Managed Streaming for Apache Kafka (MSK) cluster with 3 broker nodes. The program includes the necessary configurations for the MSK cluster, including the broker node group information, security groups, and IAM roles. The AWS provider is configured with a default region and credentials.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# Create an IAM role for MSK
resource "aws_iam_role" "msk_role" {
  name = "msk-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

# Create an IAM policy for MSK
resource "aws_iam_policy" "msk_policy" {
  name        = "msk-policy"
  description = "Policy for MSK cluster"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "kafka:*"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach the policy to the IAM role
resource "aws_iam_role_policy_attachment" "msk_policy_attach" {
  policy_arn = aws_iam_policy.msk_policy.arn
  role       = aws_iam_role.msk_role.name
}

# Create a security group for MSK
resource "aws_security_group" "msk_sg" {
  name        = "msk-sg"
  description = "Security group for MSK cluster"
  vpc_id      = "vpc-12345678"  # Replace with your VPC ID

  ingress {
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]  # Replace with your CIDR block
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Create a subnet group for MSK
resource "aws_msk_configuration" "msk_config" {
  name                = "msk-config"
  kafka_versions      = ["2.8.0"]
  server_properties   = <<PROPERTIES
auto.create.topics.enable = true
default.replication.factor = 3
min.insync.replicas = 2
PROPERTIES
}

# Create the MSK cluster
resource "aws_msk_cluster" "msk_cluster" {
  cluster_name           = "my-msk-cluster"
  kafka_version          = "2.8.0"
  number_of_broker_nodes = 3

  broker_node_group_info {
    client_subnets = ["subnet-12345678", "subnet-87654321", "subnet-13579246"]  # Replace with your subnet IDs
    instance_type    = "m5.large"
    security_groups  = [aws_security_group.msk_sg.id]
  }

  client_authentication {
    sasl {
      iam = true
    }
  }

  encryption_info {
    encryption_in_transit {
      client_broker = "TLS_PLAINTEXT"
      in_cluster    = true
    }
  }

  configuration_info {
    arn      = aws_msk_configuration.msk_config.arn
    revision = aws_msk_configuration.msk_config.latest_revision
  }

  tags = {
    Name = "MyMSKCluster"
  }
}
```

### Notes
- Ensure that the VPC ID, subnet IDs, and CIDR blocks are replaced with your actual values.
- The IAM role and policy are created with basic permissions. You may need to adjust the policy to fit your specific requirements.
- The MSK cluster is configured with a basic server properties file. You can customize this file based on your needs.

