### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_iam_role" "msk_cluster_role" {
  name = "msk-cluster-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kafka.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name = "msk-cluster-role"
  }
}

resource "aws_msk_cluster" "serverless_msk_cluster" {
