  name = "/aws/msk/my-msk-cluster"
}

resource "aws_s3_bucket" "msk_s3_bucket" {
  bucket = "my-msk-cluster-logs-bucket"
}

resource "aws_kinesis_firehose_delivery_stream" "msk_firehose_delivery_stream" {
  name       = "my-msk-cluster-firehose-stream"
  destination = "extended_s3"

  extended_s3_configuration {
    role_arn   = aws_iam_role.msk_firehose_role.arn
    bucket_arn = aws_s3_bucket.msk_s3_bucket.arn
  }
}

resource "aws_iam_role" "msk_firehose_role" {
  name = "msk-firehose-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "msk_firehose_policy" {
  name = "msk-firehose-policy"
  role = aws_iam_role.msk_firehose_role.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:AbortMultipartUpload",
          "s3:GetBucketLocation",
          "s3:GetObject",
          "s3:ListBucket",
          "s3:ListBucketMultipartUploads",
          "s3:PutObject"
        ]
        Effect = "Allow"
        Resource = [
          aws_s3_bucket.msk_s3_bucket.arn,
          "${aws_s3_bucket.msk_s3_bucket.arn}/*"
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "msk_firehose_policy_attachment" {
  policy_arn = aws_iam_role_policy.msk_firehose_policy.arn
  role       = aws_iam_role.msk_firehose_role.name
}
