provider "aws" {
  region = "us-west-2"
}

variable "environment" {
  description = "Environment name for resources"
  default     = "dev"
}

resource "aws_s3_bucket" "msk_s3_bucket" {
  bucket = "msk-output-bucket-${var.environment}"
  acl    = "private"
}

resource "aws_cloudwatch_log_group" "msk_log_group" {
  name = "/aws/msk/cluster/${var.environment}"
}

resource "aws_kinesis_firehose_delivery_stream" "msk_firehose_delivery_stream" {
  name       = "msk-firehose-stream-${var.environment}"
  destination = "s3"

  s3_configuration {
    role_arn           = aws_iam_role.firehose_role.arn
    bucket_arn         = aws_s3_bucket.msk_s3_bucket.arn
    prefix             = "logs/"
    buffering_interval = 60
    buffering_size     = 5
  }

  cloudwatch_logging_options {
    enabled         = true
    log_group_name  = aws_cloudwatch_log_group.msk_log_group.name
    log_stream_name = "firehose-log-stream"
  }
}

resource "aws_iam_role" "firehose_role" {
  name = "msk-firehose-role-${var.environment}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })
}

