          "logs:UpdateLogDelivery"
        ]
        Effect = "Allow"
        Resource = [
          aws_cloudwatch_log_group.msk_log_group.arn,
          "${aws_cloudwatch_log_group.msk_log_group.arn}/*"
        ]
      }
    ]
  })
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name           = "msk-cluster-${var.environment}"
  kafka_version          = "2.8.1"
  number_of_broker_nodes = 3

