  cidr_block              = "10.0.1.0/24"
  availability_zone       = "us-west-2a"
  map_public_ip_on_launch = true
}

resource "aws_dax_subnet_group" "my_dax_subnet_group" {
  name       = "my-dax-subnet-group"
  subnet_ids = [aws_subnet.my_subnet.id]
}
```

