This Terraform program creates an AWS Redshift cluster and configures endpoint access from two subnets. The program includes the necessary resources such as the Redshift cluster, subnets, and Redshift endpoint access configurations. The resources are interdependent, ensuring that the endpoint access configurations depend on the existence of the Redshift cluster and the subnets.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "subnet1" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "subnet2" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
}

resource "aws_redshift_cluster" "redshift_cluster" {
  cluster_identifier = "my-redshift-cluster"
  node_type          = "dc2.large"
  master_username    = "admin"
  master_password    = "SecurePassword123!"
  iam_roles          = ["arn:aws:iam::123456789012:role/RedshiftAccessRole"]
  cluster_subnet_group_name = "my-redshift-subnet-group"
}

resource "aws_redshift_subnet_group" "redshift_subnet_group" {
  name       = "my-redshift-subnet-group"
  subnet_ids = [aws_subnet.subnet1.id, aws_subnet.subnet2.id]
}

resource "aws_redshift_endpoint_access" "redshift_endpoint_access1" {
  cluster_identifier = aws_redshift_cluster.redshift_cluster.cluster_identifier
  endpoint_name      = "redshift-endpoint-access1"
  subnet_group_name  = aws_redshift_subnet_group.redshift_subnet_group.name
}

resource "aws_redshift_endpoint_access" "redshift_endpoint_access2" {
  cluster_identifier = aws_redshift_cluster.redshift_cluster.cluster_identifier
  endpoint_name      = "redshift-endpoint-access2"
  subnet_group_name  = aws_redshift_subnet_group.redshift_subnet_group.name
}
```

