This Terraform program creates an AWS Redshift cluster with event notifications configured via Amazon SNS. The program includes the creation of an SNS topic and a subscription to that topic. The Redshift cluster is configured to send notifications to the SNS topic.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_sns_topic" "redshift_notifications" {
  name = "redshift-event-notifications"
}

resource "aws_sns_topic_subscription" "redshift_notifications_subscription" {
  endpoint = "example@example.com"
  protocol = "email"
  topic_arn  = aws_sns_topic.redshift_notifications.arn
}

resource "aws_redshift_cluster" "my_redshift_cluster" {
  cluster_identifier = "my-redshift-cluster"
  node_type          = "dc2.large"
  master_username    = "admin"
  master_password    = "SecurePassword123!"
  iam_roles          = [aws_iam_role.redshift_sns_role.arn]

  depends_on = [
    aws_sns_topic.redshift_notifications,
    aws_sns_topic_subscription.redshift_notifications_subscription
  ]
}

resource "aws_iam_role" "redshift_sns_role" {
  name = "redshift-sns-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "redshift_sns_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRedshiftClusterSNSTopicPolicy"
  role       = aws_iam_role.redshift_sns_role.name
}
```

### Explanation
1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **SNS Topic**: An SNS topic named `redshift-event-notifications` is created.
