### Description
This Terraform program defines an AWS S3 bucket to store code build output and an AWS CodeBuild project configured to build students' code. The CodeBuild project uses an S3 bucket as its artifact storage location, with specific environment settings and source configuration.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_s3_bucket" "codebuild_output_bucket" {
  bucket = "codebuild-output-bucket-${var.environment}"
  acl    = "private"
  force_destroy = true
}

resource "aws_iam_role" "codebuild_service_role" {
  name = "codebuild-service-role-${var.environment}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "codebuild_policy" {
  role       = aws_iam_role.codebuild_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSCodeBuildServiceRole"
}

resource "aws_codebuild_project" "students_codebuild_project" {
  name         = "students-codebuild-project-${var.environment}"
  service_role = aws_iam_role.codebuild_service_role.arn

  artifacts {
    type   = "S3"
    location = aws_s3_bucket.codebuild_output_bucket.bucket
  }

  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image        = "alpine"
    type         = "LINUX_CONTAINER"
  }

  source {
    type            = "GITHUB"
    location        = "github.com/source-location"
    git_clone_depth = 1
  }
}

variable "environment" {
  description = "Environment tag for resources"
  default     = "dev"
}
```

