### Description
This Terraform configuration sets up an AWS infrastructure to run a code every day at 7 UTC using AWS EventBridge and AWS Lambda. The configuration includes creating an IAM role for the Lambda function, defining the Lambda function itself, setting up an EventBridge rule to trigger the Lambda function daily, and granting the necessary permissions for EventBridge to invoke the Lambda function.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_iam_role" "lambda_execution_role" {
  name = "lambda_execution_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })

  inline_policy {
    name = "lambda_policy"
    policy = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Action = [
            "logs:CreateLogGroup",
            "logs:CreateLogStream",
            "logs:PutLogEvents"
          ]
          Effect = "Allow"
          Resource = "arn:aws:logs:*:*:*"
        }
      ]
    })
  }
}

resource "aws_lambda_function" "daily_task_lambda" {
  function_name = "daily_task_lambda"
  role          = aws_iam_role.lambda_execution_role.arn
  handler       = "index.handler"
  runtime       = "python3.8"

  filename         = "lambda_function.zip"
  source_code_hash = filebase64sha256("lambda_function.zip")
}

resource "aws_cloudwatch_event_rule" "daily_schedule_rule" {
  name                = "daily_schedule_rule"
  schedule_expression = "cron(0 7 * * ? *)"
}

resource "aws_cloudwatch_event_target" "lambda_target" {
  rule      = aws_cloudwatch_event_rule.daily_schedule_rule.name
  target_id = "lambda_target"
  arn       = aws_lambda_function.daily_task_lambda.arn
}

resource "aws_lambda_permission" "allow_eventbridge_invocation" {
  statement_id  = "AllowExecutionFromEventBridge"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.daily_task_lambda.function_name
  principal     = "events.amazonaws.com"
  source_arn    = aws_cloudwatch_event_rule.daily_schedule_rule.arn
}
```

### Notes
1. **IAM Role**: The `aws_iam_role` resource defines an IAM role with a trust policy allowing Lambda to assume the role and an inline policy granting permissions to write logs to CloudWatch.
2. **Lambda Function**: The `aws_lambda_function` resource defines a Lambda function with the specified handler, runtime, and code location. The `source_code_hash` is calculated using the `filebase64sha256` function.
3. **EventBridge Rule**: The `aws_cloudwatch_event_rule` resource sets up a scheduled rule to trigger at 7 UTC every day.
4. **EventBridge Target**: The `aws_cloudwatch_event_target` resource links the EventBridge rule to the Lambda function.
5. **Lambda Permission**: The `aws_lambda_permission` resource grants EventBridge permission to invoke the Lambda function.

This configuration ensures that the Lambda function is executed daily at 7 UTC, with proper IAM roles and permissions set up.

