### Description
This Terraform program sets up an AWS EventBridge event rule named "cron" that triggers a Lambda function daily at 7 UTC. The Lambda function is deployed using a ZIP file located at "./supplement/lambda_func.zip". The program includes the necessary IAM roles and configurations to ensure proper execution.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"  # Specify your desired AWS region
}

resource "aws_iam_role" "lambda_execution_role" {
  name = "lambda_execution_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })

  inline_policy {
    name = "lambda_policy"
    policy = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Action = [
            "logs:CreateLogGroup",
            "logs:CreateLogStream",
            "logs:PutLogEvents"
          ]
          Effect = "Allow"
          Resource = "arn:aws:logs:*:*:*"
        }
      ]
    })
  }
}

resource "aws_lambda_function" "lambda_function" {
  function_name = "cron_lambda"
  role          = aws_iam_role.lambda_execution_role.arn
  handler       = "index.handler"
  runtime       = "python3.8"
  filename      = "./supplement/lambda_func.zip"
}

resource "aws_cloudwatch_event_rule" "cron_event_rule" {
  name                = "cron"
  schedule_expression = "cron(0 7 * * ? *)"
}

resource "aws_cloudwatch_event_target" "lambda_target" {
  rule      = aws_cloudwatch_event_rule.cron_event_rule.name
  target_id = "lambda_target"
  arn       = aws_lambda_function.lambda_function.arn

  input = jsonencode({
    key = "value"
  })
}
```

### Explanation
1. **Provider Configuration**: The AWS provider is configured with the region set to "us-east-1".
2. **IAM Role**: An IAM role named `lambda_execution_role` is created with a trust policy allowing Lambda to assume the role. An inline policy grants permissions for logging.
3. **Lambda Function**: A Lambda function named `cron_lambda` is defined, linked to the IAM role, and uses the provided ZIP file as its deployment package.
4. **EventBridge Rule**: An EventBridge rule named `cron` is created with a schedule expression to trigger daily at 7 UTC.
5. **EventBridge Target**: The Lambda function is set as the target for the EventBridge rule, ensuring it gets invoked at the specified time.

