Description:
The Terraform program defines the infrastructure for a video streaming site with multiple servers to balance load using AWS services such as Load Balancing, Route53, VPC, and EC2. The configuration includes creating a VPC, security groups, EC2 instances, an Application Load Balancer (ALB), a target group, and DNS records in Route53. The ALB distributes traffic among the EC2 instances, and Route53 manages DNS for the domain.

Terraform HCL Program:
```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "video_streaming_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "video_streaming_subnet" {
  vpc_id            = aws_vpc.video_streaming_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_security_group" "video_streaming_sg" {
  name        = "video-streaming-sg"
  description = "Security group for video streaming instances"
  vpc_id      = aws_vpc.video_streaming_vpc.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_instance" "video_streaming_server_1" {
  ami           = "ami-0c55b159cbfafe1f0"  # Example AMI ID for Amazon Linux 2
  instance_type = "t3.micro"
  vpc_security_group_ids = [aws_security_group.video_streaming_sg.id]
  subnet_id     = aws_subnet.video_streaming_subnet.id
}

resource "aws_instance" "video_streaming_server_2" {
  ami           = "ami-0c55b159cbfafe1f0"  # Example AMI ID for Amazon Linux 2
  instance_type = "t3.micro"
  vpc_security_group_ids = [aws_security_group.video_streaming_sg.id]
  subnet_id     = aws_subnet.video_streaming_subnet.id
}

resource "aws_lb" "video_streaming_lb" {
  name               = "video-streaming-lb"
  internal           = false
  load_balancer_type = "application"

  subnet_mapping {
    subnet_id = aws_subnet.video_streaming_subnet.id
  }
}

resource "aws_lb_target_group" "video_streaming_tg" {
  name     = "video-streaming-tg"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.video_streaming_vpc.id
}

resource "aws_lb_listener" "video_streaming_listener" {
  load_balancer_arn = aws_lb.video_streaming_lb.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.video_streaming_tg.arn
  }
}

resource "aws_lb_target_group_attachment" "video_streaming_tg_attachment_1" {
  target_group_arn = aws_lb_target_group.video_streaming_tg.arn
  target_id        = aws_instance.video_streaming_server_1.id
  port             = 80
}

resource "aws_lb_target_group_attachment" "video_streaming_tg_attachment_2" {
  target_group_arn = aws_lb_target_group.video_streaming_tg.arn
  target_id        = aws_instance.video_streaming_server_2.id
  port             = 80
}

resource "aws_route53_zone" "video_streaming_domain" {
  name = "example.com"
}

resource "aws_route53_record" "video_streaming_record" {
  zone_id = aws_route53_zone.video_streaming_domain.zone_id
  name    = "www"
  type    = "A"
  ttl     = 300

  alias {
    name                   = aws_lb.video_streaming_lb.dns_name
    zone_id                = aws_lb.video_streaming_lb.zone_id
    evaluate_target_health = true
  }
}
