}

# Create an IAM role for the RDS instance
resource "aws_iam_role" "rds_iam_role" {
  name = "airbyte_rds_iam_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

# Attach the AmazonRDSFullAccess policy to the IAM role
resource "aws_iam_role_policy_attachment" "rds_full_access" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonRDSFullAccess"
  role       = aws_iam_role.rds_iam_role.name
}

# Create a DB subnet group
