  name       = "airbyte-db-subnet-group"
  subnet_ids = ["subnet-0123456789abcdef0", "subnet-0fedcba9876543210"]  # Replace with your public subnet IDs

  tags = {
    Name = "AirbyteDBSubnetGroup"
  }
}

# Create a security group for the RDS instance
