  enable_dns_hostnames = true
}

resource "aws_subnet" "my_subnet" {
  vpc_id                  = aws_vpc.my_vpc.id
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = false
}

resource "aws_security_group" "my_security_group" {
  vpc_id = aws_vpc.my_vpc.id
  name   = "postgres-sg"

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_subnet_group" "my_db_subnet_group" {
  name       = "postgres-subnet-group"
  subnet_ids = [aws_subnet.my_subnet.id]
}

resource "aws_db_instance" "my_postgres_db" {
  instance_class             = "db.t3.micro"
  engine                     = "postgres"
  engine_version             = "13.7"
  allocated_storage          = 20
  username                   = "admin"
  password                   = "password"
  db_subnet_group_name       = aws_db_subnet_group.my_db_subnet_group.name
  vpc_security_group_ids     = [aws_security_group.my_security_group.id]
  allow_major_version_upgrade = true
  auto_minor_version_upgrade  = true
  publicly_accessible        = false
}
```

This Terraform configuration sets up a PostgreSQL database instance in AWS within a custom VPC and subnet. The database allows major version upgrades and automatically performs minor version upgrades. It is not publicly accessible, and the necessary networking resources are configured accordingly.

