### Terraform HCL Program
```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_db_option_group" "option_group_pike" {
  engine_name         = "sqlserver-ee"
  major_engine_version = "11"
  name                = "option-group-pike"
  option_group_description = "Option group for SQL Server EE with major engine version 11"

  # Example of adding an option, adjust as needed
