### Description
This Terraform program creates an S3 Glacier vault and applies a Vault Lock to it. The Vault Lock ensures that the contents of the vault cannot be deleted or modified for a specified period, providing a safeguard for critical data.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_glacier_vault" "my_glacier_vault" {
  name = "my-glacier-vault"
}

resource "aws_glacier_vault_lock" "my_glacier_vault_lock" {
  complete_lock = true
  policy = jsonencode({
    Rules = [
      {
        ID          = "InitialLock"
        MinRetentionDurationInDays = 365
        MaxRetentionDurationInDays = 730
      }
    ]
  })
  vault_name = aws_glacier_vault.my_glacier_vault.name
}
```

