### Description
This Terraform program creates an S3 Glacier vault with a specific access policy defined using `aws_iam_policy_document`. The vault is then locked using `aws_glacier_vault_lock`. The program ensures that the Glacier vault depends on the access policy document and that the lock depends on the Glacier vault.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

data "aws_iam_policy_document" "glacier_access_policy" {
  statement {
    effect = "Allow"
    actions = [
      "glacier:InitiateJob",
      "glacier:GetJobOutput",
      "glacier:ListJobs",
      "glacier:DescribeVault",
      "glacier:UploadArchive",
      "glacier:InventoryRetrieval"
    ]
    resources = ["arn:aws:glacier:*:*:vaults/my-glacier-vault"]
  }
}

resource "aws_glacier_vault" "my_glacier_vault" {
  name            = "my-glacier-vault"
  access_policy   = data.aws_iam_policy_document.glacier_access_policy.json
}

resource "aws_glacier_vault_lock" "my_glacier_vault_lock" {
  vault_name    = aws_glacier_vault.my_glacier_vault.name
  complete_lock = true
  policy        = jsonencode({
    Policy = {
      Version = "2012-10-17"
      Rules   = [
        {
          ID       = "DefaultLock"
          MinDays  = 30
          MaxDays  = 365
          IsDefault = true
        }
      ]
    }
  })
}
```

This configuration sets up an S3 Glacier vault named `my-glacier-vault` with a specific access policy that allows certain operations on the vault. The vault is then locked with a policy that specifies a minimum and maximum retention period of 30 and 365 days, respectively.

