Description:
The Terraform program defines an Application Load Balancer (ALB) with a listener and a listener rule that uses a fixed-response action. The fixed-response action returns a plain text message with a status code of 200 when the path pattern matches "/fixed-response". The ALB is configured to be internet-facing and is associated with a specified subnet and security group.

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_lb" "my_load_balancer" {
  name               = "my-alb"
  internal           = false
  load_balancer_type = "application"

  subnet_mapping {
    subnet_id = "subnet-0123456789abcdef0"
  }

  security_groups = ["sg-0123456789abcdef0"]
}

resource "aws_lb_listener" "my_listener" {
  load_balancer_arn = aws_lb.my_load_balancer.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    type             = "fixed-response"
    fixed_response {
      content_type = "text/plain"
      message_body = "Default Fixed Response Content"
      status_code  = "200"
    }
  }
}

resource "aws_lb_listener_rule" "my_listener_rule" {
  listener_arn = aws_lb_listener.my_listener.arn
  priority     = 1

  action {
    type             = "fixed-response"
    fixed_response {
      content_type = "text/plain"
      message_body = "Fixed Response Content"
      status_code  = "200"
    }
  }

  condition {
    field  = "path-pattern"
    values = ["/fixed-response"]
  }
}
```

This configuration ensures that the ALB, listener, and listener rule are correctly set up with the fixed-response action. The `aws_lb_listener` resource includes a default action with a fixed response, and the `aws_lb_listener_rule` resource specifies a condition to match the path pattern "/fixed-response" and returns a different fixed response.

