  acl    = "private"
}

resource "aws_iam_role" "db_restore_role" {
  name = "db-restore-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "db_restore_policy" {
  name        = "db-restore-policy"
  description = "Policy for RDS to restore from S3"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Effect   = "Allow"
        Resource = [
          "${aws_s3_bucket.db_backup_bucket.arn}",
          "${aws_s3_bucket.db_backup_bucket.arn}/*"
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_db_restore_policy" {
  role       = aws_iam_role.db_restore_role.name
  policy_arn = aws_iam_policy.db_restore_policy.arn
}

resource "aws_db_instance" "restored_db_instance" {
  instance_class = "db.t3.micro"
  engine         = "mysql"
  engine_version = "8.0"
  username       = "admin"
  password       = "password"
  allocated_storage = 20

  s3_import {
    bucket_name     = aws_s3_bucket.db_backup_bucket.bucket
    ingestion_role  = aws_iam_role.db_restore_role.arn
    source_engine   = "mysql"
    source_engine_version = "8.0"
  }
}
```

This Terraform configuration sets up an AWS environment to restore a database from an S3 bucket. It includes:

1. An S3 bucket (`aws_s3_bucket.db_backup_bucket`) to store the database backup.
2. An IAM role (`aws_iam_role.db_restore_role`) with a trust policy allowing RDS to assume it.
3. An IAM policy (`aws_iam_policy.db_restore_policy`) granting the necessary permissions for the role to access the S3 bucket.
4. An IAM role policy attachment (`aws_iam_role_policy_attachment.attach_db_restore_policy`) to attach the policy to the role.
5. An RDS instance (`aws_db_instance.restored_db_instance`) configured to restore from the S3 bucket using the IAM role.

